{"content": "class Controller:
    def __init__(self):
        self.generation = 0
        self.rows = []
        self.decisions = {}
        self.busy = False
        self._has_pending_result = False  # whether we have a completed generation waiting for finish

    def start(self):
        self.generation += 1
        self.busy = True
        return self.generation

    def poll_status(self, generation, status):
        # Stale/duplicate statuses return False
        if generation != self.generation:
            return False

        # queued/running keep busy
        if status in ('queued', 'running'):
            return False

        # failed ends busy without fetching
        if status == 'failed':
            self.busy = False
            return False

        # completed returns True ONCE for latest running generation transitioning to completed
        if status == 'completed':
            if self._has_pending_result:
                # Already had a pending result, this is a duplicate
                return False
            self._has_pending_result = True
            return True

        return False

    def finish(self, generation, rows):
        # finish accepts only latest completed pending results once
        # stale/unrequested finish returns False

        # Must be latest generation and have pending result
        if generation != self.generation:
            return False

        if not self._has_pending_result:
            return False

        # Accept the result, copy rows, end busy
        self.rows = list(rows)
        self._has_pending_result = False
        self.busy = False
        return True

    def set_decision(self, job_id, value):
        # persists independent of all refreshes
        self.decisions[job_id] = value"}

